// 1. Linear Search - O(n): dùng được cả với mảng chưa sắp xếp
int linearSearch(const vector<int>& a, int x) {
    for (int i = 0; i < (int)a.size(); i++) if (a[i] == x) return i;
    return -1;
}

// 2. Binary Search - O(log n): mảng PHẢI đã sắp xếp. Khoảng đóng [trai, phai]
int binarySearch(const vector<int>& a, int x) {
    int trai = 0, phai = (int)a.size() - 1;
    while (trai <= phai) {
        int giua = trai + (phai - trai) / 2; // tránh tràn số so với (trai + phai) / 2
        if (a[giua] == x) return giua;
        if (a[giua] < x) trai = giua + 1;    // bỏ nửa trái
        else phai = giua - 1;                // bỏ nửa phải
    }
    return -1;
}

// 3. Lower bound: vị trí đầu tiên có giá trị >= x. Khoảng nửa mở [trai, phai)
int lowerBound(const vector<int>& a, int x) {
    int trai = 0, phai = a.size();
    while (trai < phai) {
        int giua = trai + (phai - trai) / 2;
        if (a[giua] < x) trai = giua + 1;
        else phai = giua;
    }
    return trai;
}

// 4. Upper bound: vị trí đầu tiên có giá trị > x
int upperBound(const vector<int>& a, int x) {
    int trai = 0, phai = a.size();
    while (trai < phai) {
        int giua = trai + (phai - trai) / 2;
        if (a[giua] <= x) trai = giua + 1;
        else phai = giua;
    }
    return trai;
}

